			declare @nh_vv1 varchar(1024), @q nvarchar(max) = '	'
			select @nh_vv1 = nh_vv1 from @@table where nh_vv1 = @nh_vv1 
			select id, ltrim(data) data into #ds_da from dbo.FastBusiness$Function$System$Split(@nh_vv1, ',')
			select @q += b.ten_nh%l + ',' from #ds_da a join  dmnhvv b on a.data = b.ma_nh order by a.id
