select @tu_ngay as tu_ngay, @den_ngay as den_ngay
exec zrpt_O047_new @tu_ngay, @den_ngay, @nh_vv1, @loai_sp, @kieu_sp, @ma_hd, @ma_vv, @ma_kh, @ma_dvcs, '@@sysDatabaseName', @@language, @@userID, @@admin

			
		
	

	
		
