function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete); 
	changeLookupReadonly(f, 'ma_dvcs');
	changeLookupReadonly(f, 'nh_vv1');
	changeLookupReadonly(f, 'loai_sp');
	changeLookupReadonly(f, 'kieu_sp');
	if (defaultUnit) f.setItemValue('ma_dvcs', defaultUnit);
}
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}
}


function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid, v = f.getItem('mau_bc').value; 
			g._hiddenForms = [];
			g._alterTitle = [null, [['%s1', f.getItem('tu_ngay').value, true], ['%s2', f.getItem('den_ngay').value, true], ['%s3', f.getItem('ten_nh_1').value, true]]];
			var _ten = 'Báo cáo chi tiết bán ra - ' + f.getItemValue('ten_nh_1%l');
			var _ten2 = 'Sales report details - ' + f.getItemValue('ten_nh_1%l');
			g._title = f._language == 'v' ? _ten : _ten2;
			g._queryFilterString = getQueryFilterString(f, 'tu_ngay, den_ngay, ma_dvcs');
			//remove$GridReport$Filter(g);
			break;
		case 'ProjectValue':
			f.setItemValue('ten_nh_1', result[0].Value);
			break;
		default:
			break;
	}
}

function onChange$nh_vv1(o) {
	var f = o.parentForm;
	var ob = f.getItem('nh_vv1')._controlBehavior;
	var s = ob._lookupResult && ob._lookupResult.filter(function(e) {
		return ob._selectedKeyList.includes(e[0]);
	}).map(function(e) {return e[1]}).join(',')

	f.request('ProjectValue', 'ProjectValue', ['nh_vv1'], null);
	
}

		
	

		
			
				
		
